  compile(SOURCE,str(target),'exec')
  backup=state/'deployments'/('memory-connection-v12-'+str(time.time_ns()))
  backup.mkdir(parents=True,mode=0o700)
  (backup/target.name).write_bytes(old)
  fd,tmp=tempfile.mkstemp(dir=code,prefix='.memory-connection-')
  try:
   with os.fdopen(fd,'wb') as f:f.write(SOURCE);f.flush();os.fsync(f.fileno())
   if target.read_bytes()!=old:raise RuntimeError('검증 중 코드가 변경됨. 적용 중단')
   os.chmod(tmp,target.stat().st_mode & 0o777)
   os.replace(tmp,target)
  finally:
   if os.path.exists(tmp):os.unlink(tmp)
  print('기억 도구 실행 위치 local 및 서버 코드 경로 적용 완료')
